declare const url: string, prefetched: { blob: Blob | null };
// Activation comes from keydown, mousedown, pointerdown (mouse), pointerup/touchend (touch). It is short-lived.
document.querySelector('#share')?.addEventListener('click', () => {
  void navigator.share({ url }); // call the gated API first, synchronously
  // await fetch(...) and THEN share -> NotAllowedError (especially Safari). Fetch before the tap instead.
});
document.querySelector('#copy-image')?.addEventListener('click', () => {
  if (prefetched.blob) void navigator.clipboard.write([new ClipboardItem({ [prefetched.blob.type]: prefetched.blob })]);
});
export const mayAutoplay = () => navigator.userActivation?.hasBeenActive === true; // sticky: the user has interacted once

declare const card: HTMLElement, turnOn: HTMLButtonElement, enabledState: () => HTMLElement, howToEnable: () => HTMLElement;
// 1. Render your own explainer card where the feature lives ('Get a ping when someone mentions you'), not on load.
// 2. Only the user's tap on 'Turn on' triggers the browser prompt.
turnOn.addEventListener('click', async () => {
  const result = await Notification.requestPermission();
  card.replaceWith(result === 'granted' ? enabledState() : howToEnable()); // 3. denied -> show settings steps; never re-prompt on your own
  localStorage.setItem('notif-asked', String(Date.now())); // don't nag: remember a 'Not now'
});
// Capability elements (progressive enhancement; the fallback content renders elsewhere):
// <geolocation><button type="button">Use my location</button></geolocation>
// <usermedia><button type="button">Turn on camera</button></usermedia>

/** Names differ per browser ('clipboard-read' is Chromium-only); unknown names throw TypeError. */
export async function permission(name: string): Promise<PermissionState | 'unsupported'> {
  try {
    const status = await navigator.permissions.query({ name } as PermissionDescriptor); // lib's PermissionName is a short list
    return status.state;
  } catch {
    return 'unsupported';
  }
}
/** Re-render when the user flips it in browser/OS settings. */
export async function watchPermission(name: PermissionName, onChange: (s: PermissionState) => void) {
  const status = await navigator.permissions.query({ name }).catch(() => null);
  if (!status) return;
  onChange(status.state);
  status.addEventListener('change', () => onChange(status.state));
}
// Chromium needs the extra field for push: navigator.permissions.query({ name: 'push', userVisibleOnly: true })

/** System share sheet; falls back (copy link) where there is none. Call straight from the click: no await before it. */
export async function share(data: ShareData, fallback: () => void): Promise<void> {
  if (typeof navigator.share !== 'function' || (navigator.canShare && !navigator.canShare(data))) return fallback();
  try {
    await navigator.share(data);
  } catch (e) {
    if (e instanceof DOMException && e.name === 'AbortError') return; // user closed the sheet: not an error
    toast(`Couldn't share: ${e instanceof Error ? e.message : String(e)}`); // NotAllowedError, InvalidStateError, DataError
  }
}
// Files: build the File BEFORE the tap. Chrome only allows image/video/audio/PDF/text types.
const file = new File([new Blob(['hi'])], 'note.txt', { type: 'text/plain' });
document.querySelector('button')?.addEventListener('click', () => void share({ files: [file], title: 'Note' }, copyLink));

// manifest.webmanifest
"share_target": {
  "action": "/share-target", "method": "POST", "enctype": "multipart/form-data",
  "params": { "title": "title", "text": "text", "url": "url",
    "files": [{ "name": "media", "accept": ["image/*", "video/*", ".pdf"] }] }
}
// sw.ts
/// <reference lib="webworker" />
declare const self: ServiceWorkerGlobalScope;
self.addEventListener('fetch', (e) => {
  const url = new URL(e.request.url);
  if (e.request.method !== 'POST' || url.pathname !== '/share-target') return;
  e.respondWith((async () => {
    const form = await e.request.formData();
    const files = form.getAll('media').filter((f): f is File => f instanceof File);
    const cache = await caches.open('share-inbox'); // or IndexedDB; the page reads them after the redirect
    await Promise.all(files.map((f, i) => cache.put(`/share-inbox/${i}`, new Response(f, { headers: { 'content-type': f.type } }))));
    const text = form.get('text');
    const q = new URLSearchParams({ files: String(files.length), text: typeof text === 'string' ? text : '' });
    return Response.redirect(`/?${q}#share`, 303); // 303: a reload must not re-POST
  })());
});
// Text/URL only: "method": "GET" and read new URLSearchParams(location.search) on load.

/** Unread count on the installed app's icon. Outside an installed app it rejects or no-ops: expected, not an error. */
export function setBadge(n: number): void {
  const asked = n > 0 ? navigator.setAppBadge?.(n) : navigator.clearAppBadge?.();
  asked?.catch(() => {});
}
// sw.ts: keep it right while the app is closed
self.addEventListener('push', (e) => {
  e.waitUntil(self.navigator.setAppBadge?.(unreadFrom(e.data)) ?? Promise.resolve());
});

// page
export const canNotify = () => 'Notification' in window && 'serviceWorker' in navigator; // false in an iOS Safari tab
type Action = { action: string; title: string };
export async function notify(title: string, body: string, tag: string, data: { url: string }, actions: Action[] = []) {
  const reg = await navigator.serviceWorker.ready;
  if (typeof reg.showNotification !== 'function') return; // Safari tab: a worker without notifications
  const max = 'maxActions' in Notification && typeof Notification.maxActions === 'number' ? Notification.maxActions : 0;
  const options: NotificationOptions & { actions?: Action[] } = { body, tag, data, icon: '/icon-192.png', badge: '/badge-96.png' };
  if (max > 0) options.actions = actions.slice(0, max);
  await reg.showNotification(title, options);
}
/** Safari ignores `tag` replacement: close stale ones yourself when the conversation is read. */
export async function clearNotifications(tag: string) {
  const reg = await navigator.serviceWorker.ready;
  if (typeof reg.getNotifications !== 'function') return;
  for (const n of await reg.getNotifications({ tag })) n.close();
}
// sw.ts
const urlOf = (d: unknown): string | null =>
  typeof d === 'object' && d !== null && 'url' in d && typeof d.url === 'string' && d.url.startsWith('/') ? d.url : null;
self.addEventListener('notificationclick', (e) => {
  e.notification.close();
  const url = urlOf(e.notification.data); // data is untrusted: validate
  if (!url) return;
  e.waitUntil((async () => {
    const [win] = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    if (!win) return void (await self.clients.openWindow(url));
    win.postMessage({ type: 'open', url, action: e.action }); // route in-app: no reload, no second window
    await win.focus();
  })());
});

declare const saveDraft: () => void, pausePolling: () => void, resumePolling: () => void, refreshIfStale: () => void, setPresence: (p: 'online' | 'away') => void;
document.addEventListener('visibilitychange', () => {
  if (document.visibilityState === 'hidden') { saveDraft(); pausePolling(); setPresence('away'); } // last reliable moment on mobile
  else { resumePolling(); refreshIfStale(); setPresence('online'); }
});
window.addEventListener('pagehide', saveDraft); // never 'unload': unreliable on mobile and blocks the back/forward cache
window.addEventListener('pageshow', (e) => { if (e.persisted) refreshIfStale(); }); // restored from bfcache

declare const connect: () => WebSocket, handle: (m: unknown) => void, refreshToken: () => Promise<void>;
const bc = new BroadcastChannel('app-events');
/** One tab owns the socket; others hear relayed events. When the leader tab closes, a waiting tab gets the lock. */
void navigator.locks.request('app:leader', async () => {
  const ws = connect();
  ws.addEventListener('message', (m) => { handle(m.data); bc.postMessage(m.data); }); // postMessage never echoes to the sender
  await new Promise<never>(() => {}); // hold the lock for this tab's lifetime
});
bc.addEventListener('message', (e: MessageEvent<unknown>) => handle(e.data)); // other tabs (maybe another app version): validate
/** Mutual exclusion across tabs: only one refresh at a time. */
export const refreshOnce = () => navigator.locks.request('auth:refresh', refreshToken);

declare const attach: (files: File[]) => void, composer: HTMLTextAreaElement;
/** Inside the click; report a refusal (no permission / unfocused document) instead of swallowing it. */
export const copyText = (text: string) =>
  navigator.clipboard.writeText(text).then(() => toast('Copied'), (e: unknown) => toast(`Couldn't copy: ${String(e)}`));
/** Data still being fetched: pass a Promise so Safari keeps the user gesture (an await before write() loses it). */
export function copyImage(url: string) {
  if (typeof ClipboardItem === 'undefined' || !ClipboardItem.supports?.('image/png')) return copyText(url);
  const png = fetch(url).then((r) => r.blob()); // must already be image/png; convert other types via canvas first
  return navigator.clipboard.write([new ClipboardItem({ 'image/png': png })]);
}
export const copyRich = (html: string, plain: string) =>
  navigator.clipboard.write([new ClipboardItem({ 'text/html': new Blob([html], { type: 'text/html' }), 'text/plain': new Blob([plain], { type: 'text/plain' }) })]);
// Paste: the paste event needs no permission and no prompt in any browser.
composer.addEventListener('paste', (e) => {
  const files = [...(e.clipboardData?.files ?? [])];
  if (files.length) { e.preventDefault(); attach(files); }
});

declare const zone: HTMLElement, attach: (files: File[]) => void;
zone.addEventListener('dragover', (e) => {
  if (!e.dataTransfer?.types.includes('Files')) return; // ignore text/link drags
  e.preventDefault(); // makes it a drop target
  e.dataTransfer.dropEffect = 'copy';
  zone.dataset.dragging = 'true';
});
zone.addEventListener('dragleave', (e) => { if (e.target === zone) delete zone.dataset.dragging; }); // children fire dragleave too
zone.addEventListener('drop', (e) => {
  e.preventDefault();
  delete zone.dataset.dragging;
  // Read everything synchronously: the DataTransfer is emptied once the handler returns (before any await).
  const entries = [...(e.dataTransfer?.items ?? [])].map((i) => i.webkitGetAsEntry()).filter((x) => x !== null);
  const files = [...(e.dataTransfer?.files ?? [])];
  if (entries.some((x) => x.isDirectory)) toast('Folders aren’t supported yet'); // or walk FileSystemDirectoryEntry.createReader()
  if (files.length) attach(files);
});
// A file dropped beside the zone must not navigate the app away to file://…
window.addEventListener('dragover', (e) => e.preventDefault());
window.addEventListener('drop', (e) => e.preventDefault());

// Types: npm i -D @types/wicg-file-system-access (not in TS lib.dom). Minimal local shapes:
type Picker = { showOpenFilePicker?: (o?: { types?: { description?: string; accept: Record<string, string[]> }[]; multiple?: boolean }) => Promise<FileSystemFileHandle[]>;
  showSaveFilePicker?: (o?: { suggestedName?: string }) => Promise<FileSystemFileHandle> };
const w: Window & Picker = window;
const isAbort = (e: unknown) => e instanceof DOMException && e.name === 'AbortError'; // user cancelled the picker
export async function saveFile(blob: Blob, name: string) {
  if (w.showSaveFilePicker) {
    try {
      const handle = await w.showSaveFilePicker({ suggestedName: name });
      const out = await handle.createWritable();
      await out.write(blob);
      await out.close();
      return;
    } catch (e) { if (isAbort(e)) return; throw e; }
  }
  const a = Object.assign(document.createElement('a'), { href: URL.createObjectURL(blob), download: name });
  a.click();
  setTimeout(() => URL.revokeObjectURL(a.href), 30_000);
}
// open: w.showOpenFilePicker?.({ types: [{ description: 'Images', accept: { 'image/*': ['.png', '.jpg', '.webp'] } }] })
// else: create <input type=file>, listen to 'change' and 'cancel', input.click() inside the same tap.

declare const audio: HTMLAudioElement, prev: () => void, next: () => void, toggleMic: () => void, toggleCam: () => void, leave: () => void;
/** setActionHandler throws for actions a browser doesn't know; TS 5.9's MediaSessionAction also lacks the call actions. */
function setAction(action: string, handler: ((d: MediaSessionActionDetails) => void) | null) {
  try { Reflect.apply(navigator.mediaSession.setActionHandler, navigator.mediaSession, [action, handler]); } catch { /* unsupported */ }
}
if ('mediaSession' in navigator) {
  navigator.mediaSession.metadata = new MediaMetadata({ title: 'Episode 12', artist: 'Yurt Radio', album: 'Season 2',
    artwork: [{ src: '/art-96.png', sizes: '96x96', type: 'image/png' }, { src: '/art-512.png', sizes: '512x512', type: 'image/png' }] });
  setAction('play', () => void audio.play());
  setAction('pause', () => audio.pause());
  setAction('previoustrack', prev);
  setAction('nexttrack', next);
  setAction('seekto', (d) => { if (d.seekTime !== undefined) audio.currentTime = d.seekTime; });
  audio.addEventListener('timeupdate', () => {
    if (Number.isFinite(audio.duration)) navigator.mediaSession.setPositionState({ duration: audio.duration, playbackRate: audio.playbackRate, position: audio.currentTime });
  });
  setAction('togglemicrophone', toggleMic); // calls
  setAction('togglecamera', toggleCam);
  setAction('hangup', leave);
}
export function reportCallState(micOn: boolean, camOn: boolean) {
  if (!('mediaSession' in navigator)) return;
  navigator.mediaSession.setMicrophoneActive?.(micOn)?.catch(() => {});
  navigator.mediaSession.setCameraActive?.(camOn)?.catch(() => {});
}

type AudioSessionType = 'auto' | 'playback' | 'transient' | 'transient-solo' | 'ambient' | 'play-and-record';
// Not in TS's lib.dom yet; Safari-only today.
const nav: Navigator & { audioSession?: { type: AudioSessionType } } = navigator;
/** One page-wide setting; set it before the audio starts. */
export function setAudioSession(type: AudioSessionType) {
  if (nav.audioSession) nav.audioSession.type = type;
}
setAudioSession('ambient'); // UI sounds mix with the user's music instead of stopping it
export async function startCall() {
  setAudioSession('play-and-record'); // before getUserMedia
  return navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true } });
}
export const endCall = () => setAudioSession('ambient');

const ring = Object.assign(new Audio('/ringtone.wav'), { loop: true });
let unlocked = false;
/** Browsers only play sound a gesture started; iOS needs that same element later. Prime it muted inside the first tap. */
function unlock() {
  if (unlocked) return;
  ring.muted = true;
  ring.play().then(
    () => { unlocked = true; ring.pause(); ring.currentTime = 0; ring.muted = false; },
    () => {}, // not allowed yet: the next gesture tries again
  );
}
for (const t of ['pointerdown', 'pointerup', 'keydown'] as const) window.addEventListener(t, unlock, { capture: true, passive: true });
export const canSound = () => unlocked || navigator.userActivation?.hasBeenActive === true;
export const startRinging = () => void ring.play().catch(() => {});
// WebAudio: create one AudioContext and call ctx.resume() inside the first gesture.

let wanted = false;
let sentinel: WakeLockSentinel | null = null;
async function acquire() {
  if (!('wakeLock' in navigator) || sentinel || document.visibilityState !== 'visible') return;
  try {
    sentinel = await navigator.wakeLock.request('screen');
    sentinel.addEventListener('release', () => { sentinel = null; });
  } catch { /* NotAllowedError: battery saver, policy, or page hidden — just carry on */ }
}
/** Keep the screen on while it matters (call, recipe, slides, QR code on screen). */
export async function keepAwake(on: boolean) {
  wanted = on;
  if (on) await acquire();
  else { await sentinel?.release(); sentinel = null; }
}
// The browser drops the lock whenever the page is hidden; take it again on return.
document.addEventListener('visibilitychange', () => { if (wanted) void acquire(); });

type SafariVideo = HTMLVideoElement & { webkitSupportsPresentationMode?: (m: string) => boolean; webkitSetPresentationMode?: (m: string) => void };
/** From a click. Works for WebRTC streams too. */
export async function togglePip(video: SafariVideo) {
  if (document.pictureInPictureElement) return document.exitPictureInPicture();
  if (document.pictureInPictureEnabled && !video.disablePictureInPicture) return void (await video.requestPictureInPicture());
  if (video.webkitSupportsPresentationMode?.('picture-in-picture')) video.webkitSetPresentationMode?.('picture-in-picture');
}
// video.addEventListener('enterpictureinpicture' | 'leavepictureinpicture', …) to swap the inline area for a placeholder

type DocPip = { requestWindow(o?: { width?: number; height?: number; disallowReturnToOpener?: boolean; preferInitialWindowPlacement?: boolean }): Promise<Window>; readonly window: Window | null };
const w: Window & { documentPictureInPicture?: DocPip } = window;
/** From a click. */
export async function popOut(node: HTMLElement, home: HTMLElement) {
  if (!w.documentPictureInPicture) return false;
  const pip = await w.documentPictureInPicture.requestWindow({ width: 360, height: 220 });
  for (const sheet of [...document.styleSheets]) {
    try {
      const style = pip.document.createElement('style');
      style.textContent = [...sheet.cssRules].map((r) => r.cssText).join('\n');
      pip.document.head.append(style);
    } catch {
      if (!sheet.href) continue; // cross-origin sheet: link it instead
      pip.document.head.append(Object.assign(pip.document.createElement('link'), { rel: 'stylesheet', href: sheet.href }));
    }
  }
  pip.document.body.append(node); // moves the live node (listeners and state survive)
  pip.addEventListener('pagehide', () => home.append(node), { once: true });
  return true;
}

type IosVideo = HTMLVideoElement & { webkitEnterFullscreen?: () => void };
/** From a click. iPhone has no element fullscreen: only a <video> can go fullscreen (native player). */
export async function enterFullscreen(el: HTMLElement) {
  if (document.fullscreenEnabled) return el.requestFullscreen({ navigationUI: 'hide' });
  if (el instanceof HTMLVideoElement) { const v: IosVideo = el; v.webkitEnterFullscreen?.(); }
}
document.addEventListener('fullscreenchange', () => document.body.classList.toggle('is-fullscreen', !!document.fullscreenElement));
/* CSS */ /* :fullscreen { background: var(--bg); } ::backdrop { background: black; } */

type Lockable = ScreenOrientation & { lock?: (o: 'any' | 'natural' | 'landscape' | 'portrait' | 'portrait-primary' | 'portrait-secondary' | 'landscape-primary' | 'landscape-secondary') => Promise<void> };
export async function lockLandscape(el: HTMLElement): Promise<boolean> {
  try {
    if (!document.fullscreenElement) await el.requestFullscreen({ navigationUI: 'hide' });
    const o: Lockable = screen.orientation; // lock() was dropped from TS's lib.dom
    await o.lock?.('landscape');
    return typeof o.lock === 'function';
  } catch {
    return false; // NotSupportedError (desktop, iOS) / SecurityError: design for both orientations instead
  }
}
screen.orientation.addEventListener('change', () => console.log(screen.orientation.type));
// manifest (installed apps): "orientation": "portrait"

declare const video: HTMLVideoElement; // <video autoplay playsinline muted></video>  (playsinline: else iOS goes fullscreen)
let stream: MediaStream | undefined;
export async function startCamera(facing: 'user' | 'environment') {
  stream?.getTracks().forEach((t) => t.stop()); // release first (iOS may end the old camera track anyway)
  stream = await navigator.mediaDevices.getUserMedia({
    video: { facingMode: { ideal: facing }, width: { ideal: 1280 }, height: { ideal: 720 } }, audio: false });
  video.srcObject = stream;
  video.classList.toggle('mirrored', facing === 'user'); // .mirrored { transform: scaleX(-1) } like the native camera
}
export async function torch(on: boolean) {
  const track = stream?.getVideoTracks()[0];
  if (!track || !('torch' in track.getCapabilities())) return false; // Chrome Android only
  const torchOn: MediaTrackConstraintSet & { torch: boolean } = { torch: on };
  await track.applyConstraints({ advanced: [torchOn] });
  return true;
}
export const stopCamera = () => stream?.getTracks().forEach((t) => t.stop()); // camera light off = trust
// <usermedia id="cam"><button type="button" id="cam-fallback">Turn on camera</button></usermedia>
type UserMediaEl = HTMLElement & { readonly stream: MediaStream | null; setConstraints(c: MediaStreamConstraints): void };
const el = document.getElementById('cam');
const isUserMediaEl = (x: HTMLElement | null): x is UserMediaEl => !!x && 'HTMLUserMediaElement' in window && 'setConstraints' in x;
if (isUserMediaEl(el)) { el.setConstraints({ video: { facingMode: 'user' }, audio: true }); el.addEventListener('stream', () => { video.srcObject = el.stream; }); }

declare const show: (p: GeolocationPosition) => void, explainDenied: () => void;
// <geolocation><button id="near-me" type="button">Use my location</button></geolocation>
const geo = document.querySelector('geolocation');
if (geo && 'HTMLGeolocationElement' in window) {
  geo.addEventListener('location', () => {
    if ('position' in geo && geo.position instanceof GeolocationPosition) show(geo.position);
    else explainDenied();
  });
} else {
  document.getElementById('near-me')?.addEventListener('click', () =>
    navigator.geolocation.getCurrentPosition(show, (err) => { if (err.code === err.PERMISSION_DENIED) explainDenied(); }, {
      enableHighAccuracy: false, // fast and cheap first; ask for high accuracy only when the feature needs it
      maximumAge: 60_000,
      timeout: 10_000,
    }));
}

/** From a tap. iOS (and Chrome 151+) gate motion data behind requestPermission(); others just fire events. */
export async function enableTilt(onTilt: (e: DeviceOrientationEvent) => void): Promise<boolean> {
  if ('requestPermission' in DeviceOrientationEvent && typeof DeviceOrientationEvent.requestPermission === 'function') {
    const state: unknown = await DeviceOrientationEvent.requestPermission();
    if (state !== 'granted') return false;
  }
  window.addEventListener('deviceorientation', onTilt); // attach in every branch: the method's presence no longer means iOS
  return true;
}
// Chromium-only alternative with a sample rate:
// if ('Accelerometer' in window) { const s = new Accelerometer({ frequency: 30 }); s.addEventListener('reading', …); s.start(); }

type Watcher = EventTarget & { requestClose(): void; close(): void; destroy(): void; onclose: (() => void) | null; oncancel: ((e: Event) => void) | null };
const w: Window & { CloseWatcher?: new () => Watcher } = window;
/** A custom sheet/drawer that the Android back gesture, Esc and the close button all close the same way. */
export function openSheet(sheet: HTMLElement) {
  sheet.hidden = false;
  const close = () => { sheet.hidden = true; };
  const button = sheet.querySelector('[data-close]');
  if (w.CloseWatcher) {
    const watcher = new w.CloseWatcher();
    watcher.onclose = close;
    button?.addEventListener('click', () => watcher.requestClose(), { once: true });
    return;
  }
  const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') done(); };
  const done = () => { close(); window.removeEventListener('keydown', onKey); };
  window.addEventListener('keydown', onKey);
  button?.addEventListener('click', done, { once: true });
}
<!-- Prefer built-ins: --> <dialog closedby="any">…</dialog> <!-- opened with dialog.showModal() -->

type NavigateEvent = Event & { canIntercept: boolean; hashChange: boolean; downloadRequest: string | null; formData: FormData | null;
  navigationType: 'push' | 'replace' | 'reload' | 'traverse'; destination: { url: string; index: number };
  intercept(o: { handler: () => Promise<void> }): void };
type Nav = EventTarget & { currentEntry: { index: number } | null };
const w: Window & { navigation?: Nav } = window;
declare const render: (url: URL, direction: 'forward' | 'back') => Promise<void>;
w.navigation?.addEventListener('navigate', (ev) => {
  const e = ev as NavigateEvent; // lib.dom (TS 5.9) has no NavigateEvent yet
  if (!e.canIntercept || e.hashChange || e.downloadRequest !== null || e.formData) return;
  const url = new URL(e.destination.url);
  if (url.origin !== location.origin) return;
  const back = e.navigationType === 'traverse' && e.destination.index < (w.navigation?.currentEntry?.index ?? 0);
  e.intercept({ handler: () => render(url, back ? 'back' : 'forward') }); // pair with View Transitions
});

declare const settings: { haptics: boolean };
/** Short taps (8–14 ms) feel like UI feedback, not buzzing. Android only; iOS has no Vibration API. */
export function haptic(pattern: number | number[] = 10): boolean {
  if (!settings.haptics || !('vibrate' in navigator) || matchMedia('(prefers-reduced-motion: reduce)').matches) return false;
  return navigator.vibrate(pattern); // true doesn't prove it vibrated (Firefox Android returns true and does nothing)
}

declare const showBanner: (t: string) => void, hideBanner: () => void, flushOutbox: () => void;
type Conn = { saveData?: boolean; effectiveType?: 'slow-2g' | '2g' | '3g' | '4g' };
const nav: Navigator & { connection?: Conn } = navigator;
/** Chromium-only hint; treat 'unknown' as 'fine'. */
export const preferLite = () => nav.connection?.saveData === true || nav.connection?.effectiveType === 'slow-2g' || nav.connection?.effectiveType === '2g';
// onLine === false is reliable; true only means 'some network' (captive portal, LAN): confirm with a real request.
window.addEventListener('offline', () => showBanner('Offline — messages send when you’re back'));
window.addEventListener('online', () => { hideBanner(); flushOutbox(); });

// manifest.webmanifest
"launch_handler": { "client_mode": ["focus-existing", "auto"] }
// app
type LaunchParams = { readonly targetURL?: string; readonly files: readonly FileSystemHandle[] };
const w: Window & { launchQueue?: { setConsumer(cb: (p: LaunchParams) => void): void } } = window;
declare const route: (path: string) => void;
w.launchQueue?.setConsumer((p) => {
  if (p.targetURL) { const u = new URL(p.targetURL); route(u.pathname + u.hash); } // focus-existing: you navigate
});

// manifest.webmanifest
"file_handlers": [{ "action": "/open", "accept": { "text/markdown": [".md", ".markdown"] } }]
// /open
