declare const merchantSession: (validationURL: string) => Promise<unknown>, charge: (d: unknown) => Promise<boolean>;
const methods: PaymentMethodData[] = [
  { supportedMethods: 'https://apple.com/apple-pay', data: { version: 3, merchantIdentifier: 'merchant.com.example', merchantCapabilities: ['supports3DS'], supportedNetworks: ['visa', 'masterCard', 'amex'], countryCode: 'US' } },
  { supportedMethods: 'https://google.com/pay', data: { apiVersion: 2, apiVersionMinor: 0 /* …Google Pay request */ } },
];
const details: PaymentDetailsInit = { total: { label: 'Yurt Pro', amount: { currency: 'USD', value: '9.99' } } };
/** Build and show inside the click: show() needs the gesture and a request can only be shown once. */
export async function pay() {
  const req = new PaymentRequest(methods, details);
  req.addEventListener('merchantvalidation', (e) => { // Apple Pay: your server fetches a merchant session from Apple
    if ('validationURL' in e && typeof e.validationURL === 'string' && 'complete' in e && typeof e.complete === 'function') e.complete(merchantSession(e.validationURL));
  });
  const res = await req.show();
  await res.complete((await charge(res.details)) ? 'success' : 'fail');
}
export const canPay = async () => 'PaymentRequest' in window && (await new PaymentRequest(methods, details).canMakePayment().catch(() => false));

